'use strict';
const $=id=>document.getElementById(id);
const REGION_INFO={Africa:{center:[20,7],symbol:'M7 4l9-2 8 6-3 7-4 2-2 9-5-3-2-9-4-4z'},Asia:{center:[85,28],symbol:'M3 9l6-5 8 1 5-3 7 7-4 7-6-1-3 10-4-9-6 2z'},Europe:{center:[19,48],symbol:'M6 18l3-6-2-6 6-3 1 9 5-4 6 3 1 9-7 3-4-6-4 6z'},'North America':{center:[-100,30],symbol:'M3 5l12-2 10 5-4 7-7 1 2 6 7 4-7 2-7-8-3-8z'},'South America':{center:[-60,-18],symbol:'M9 3l10 2 5 8-4 4-4 10-4 2-1-13-6-6z'},Oceania:{center:[153,-19],symbol:'M3 15l7-5 8 2 2 9-8 3-7-2zM22 5l5 4M24 22l4 4'},World:{center:[15,15],symbol:''}};
const STORAGE='atlas-countries-v2';
const RANKS=[{title:'Scout',at:0},{title:'Pioneer',at:10},{title:'Explorer',at:25},{title:'Voyager',at:50},{title:'Navigator',at:100},{title:'Pathfinder',at:150},{title:'Cartographer',at:195},{title:'Atlas Master',at:207}];
let foundPlaces=new Set(),pendingCatalog=true,pendingHard=false,pendingQuick=0;
function analytics(event,params={}){if(typeof window.gtag==='function')window.gtag('event',event,params)}
function currentRank(){return [...RANKS].reverse().find(r=>foundPlaces.size>=r.at)||RANKS[0]}
function recordKey(region,extended=state?.includeTerritories){return (extended?region+'+territories':region)+(state?.hardMode?'+hard':'')}
function eligible(c){return c&&(!c.territory||state?.includeTerritories)}
function renderRanks(){const rank=currentRank(),next=RANKS.find(r=>r.at>foundPlaces.size);setText('navRank',rank.title);setText('rankTitle',rank.title);setText('rankCount',foundPlaces.size+' unique places found');setText('rankNext',next?`${next.at-foundPlaces.size} more to ${next.title}`:'The whole atlas, discovered.');$('rankBar').style.width=(next?Math.min(100,(foundPlaces.size-rank.at)/(next.at-rank.at)*100):100)+'%';$('rankLadder').innerHTML=RANKS.map(r=>`<div class="rank-step ${foundPlaces.size>=r.at?'earned':''}"><span>${foundPlaces.size>=r.at?'✧':'◇'} ${r.title}</span><small>${r.at} unique places ${rank.title===r.title?'· Your title':''}</small></div>`).join('');}

let countryFacts=null;
let audioEnabled=true,soundVolume=.65,mapTheme='midnight',uiAudio=null,glowFrame=0;
const rewardAudio={};
const MAP_THEMES={
 midnight:{ocean:'#122b38',land:'#304c50',muted:'#1a2c35',border:'#72918e',selected:'#7baf9d',selectedLine:'#d1e8bb',found:'#3d7a68',correct:'#70d2ad',miss:'#b66d63',glow:'#a8eac7',grid:'#52737d',fog:'#284850',high:'#1b3545',space:'#0b1318'},
 aurora:{ocean:'#09283a',land:'#285d62',muted:'#163c48',border:'#7cbcae',selected:'#9bceb6',selectedLine:'#d9ffe4',found:'#3d8f80',correct:'#8be8bd',miss:'#c77c8c',glow:'#b8fbd8',grid:'#5a9fa6',fog:'#315b64',high:'#163b58',space:'#08131f'},
 copper:{ocean:'#261f2e',land:'#715c50',muted:'#3e343b',border:'#d1b89a',selected:'#d6b78b',selectedLine:'#fff0cb',found:'#758c6c',correct:'#a0dcb5',miss:'#cd7b79',glow:'#d5f5bd',grid:'#a48a7c',fog:'#655059',high:'#3a2d44',space:'#17111d'},
 parchment:{ocean:'#b1c9cc',land:'#e3ddc4',muted:'#95afb0',border:'#7b7964',selected:'#a0b99b',selectedLine:'#294e3a',found:'#8cba95',correct:'#70bc8d',miss:'#cf9188',glow:'#336f4e',grid:'#78999f',fog:'#9bbfc5',high:'#536f83',space:'#101c29'}
};
function applyMapTheme(){const t=MAP_THEMES[mapTheme];$('mapTheme').value=mapTheme;if(!ready||!map.getLayer?.('countries'))return;map.setPaintProperty('ocean','background-color',t.ocean);map.setPaintProperty('grid','line-color',t.grid);map.setPaintProperty('answer-glow','line-color',t.glow);map.setPaintProperty('answer-ring','line-color',t.correct);map.setFog({color:t.fog,'high-color':t.high,'space-color':t.space,'horizon-blend':.12,'star-intensity':.16});paintCountries();}

let countries=[],geo,byId={},state,records={},map,ready=false,selected=null,hoverCode='',pendingRegion='',spinning=false,lastFrame=0,raf=0;
let reduced=window.matchMedia('(prefers-reduced-motion: reduce)').matches;

// Quiet sine/triangle envelopes echo the existing interface sounds; no audio files.
function audioStatus(text){setText('soundStatus',text)}
function getUiAudio(){try{const AudioContext=window.AudioContext||window.webkitAudioContext;if(!AudioContext)return null;if(!uiAudio||uiAudio.state==='closed')uiAudio=new AudioContext({latencyHint:'interactive'});return uiAudio}catch{return null}}
function synthSound(kind){try{const ctx=getUiAudio();if(!ctx){audioStatus('Audio is unavailable in this browser.');return}const play=()=>{if(!audioEnabled)return;if(ctx.state!=='running'){audioStatus('Audio paused — tap Test reward to enable it.');return}try{const now=ctx.currentTime;const reward=['correct','rank','complete','reward'].includes(kind);const notes=reward?[[523,523,0,.28,.12],[659,659,.12,.30,.10],[784,784,.24,.36,.09]]:kind==='miss'?[[185,150,0,.15,.04]]:kind==='next'?[[240,300,0,.09,.025]]:[[360,430,0,.08,.035]];for(const [from,to,delay,duration,level]of notes){const osc=ctx.createOscillator(),gain=ctx.createGain(),t=now+delay;osc.type=reward?'sine':'triangle';osc.frequency.setValueAtTime(from,t);osc.frequency.exponentialRampToValueAtTime(to,t+duration*.65);gain.gain.setValueAtTime(.0001,t);gain.gain.exponentialRampToValueAtTime(Math.max(.0001,level*soundVolume),t+.012);gain.gain.exponentialRampToValueAtTime(.0001,t+duration);osc.connect(gain);gain.connect(ctx.destination);osc.onended=()=>{osc.disconnect();gain.disconnect()};osc.start(t);osc.stop(t+duration+.015)}if(reward)audioStatus('Reward chime playing.')}catch{audioStatus('Audio could not start — try Test reward.')}};if(ctx.state!=='running'){Promise.resolve(ctx.resume()).then(play).catch(()=>audioStatus('Browser paused audio — tap Test reward.'))}else play()}catch{audioStatus('Audio could not start — try Test reward.')}}
function playUiSound(kind){if(!audioEnabled||soundVolume<=0)return;const isReward=['correct','rank','complete','reward'].includes(kind);if(!isReward){synthSound(kind);return}const file=kind==='rank'?'rank':kind==='complete'?'complete':'reward';try{const ctx=getUiAudio();if(ctx&&ctx.state!=='running')Promise.resolve(ctx.resume()).catch(()=>{});if(typeof window.Audio!=='function'){synthSound(kind);return}let audio=rewardAudio[file];if(!audio){audio=new window.Audio('audio/'+file+'.wav');audio.preload='auto';audio.onended=()=>{if(audioEnabled)audioStatus('Sound ready · '+Math.round(soundVolume*100)+'% volume.')};rewardAudio[file]=audio}audio.currentTime=0;audio.volume=soundVolume;const started=audio.play();if(started?.then)started.then(()=>{if(!audioEnabled)audio.pause();else audioStatus(kind==='rank'?'Rank unlocked — reward chime playing.':'Reward chime playing.')}).catch(()=>synthSound(kind))}catch{synthSound(kind)}}
function clearAnswerGlow(){cancelAnimationFrame(glowFrame);glowFrame=0;if(!ready||!map.getLayer?.('answer-glow'))return;map.setPaintProperty('answer-glow','line-opacity',0);map.setPaintProperty('answer-ring','line-opacity',0);map.setPaintProperty('small-countries','circle-stroke-width',1)}
function pulseCountry(id){clearAnswerGlow();if(!ready||!map.getLayer?.('answer-glow'))return;map.setFilter('answer-glow',['==',['get','code'],id]);map.setFilter('answer-ring',['==',['get','code'],id]);const paint=value=>{map.setPaintProperty('answer-glow','line-opacity',value*.38);map.setPaintProperty('answer-ring','line-opacity',value*.72);map.setPaintProperty('small-countries','circle-stroke-width',['case',['==',['get','code'],id],1+value*3,1])};if(reduced){paint(.5);return}let began;const tick=now=>{if(began==null)began=now;const progress=Math.min(1,(now-began)/1100);paint(Math.sin(Math.PI*progress));if(progress<1)glowFrame=requestAnimationFrame(tick);else clearAnswerGlow()};glowFrame=requestAnimationFrame(tick)}

function readSaved(){try{return JSON.parse(localStorage.getItem(STORAGE)||'null')}catch{return null}}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify({state,records,foundPlaces:[...foundPlaces],audioEnabled,soundVolume,mapTheme}))}catch{}}
function regionCountries(region,extended=state?.includeTerritories??true){return countries.filter(c=>(extended||!c.territory)&&(region==='World'||c.continent===region))}
function shuffled(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function renderRegions(){const paths=Object.entries(REGION_INFO);$('regions').innerHTML=paths.map(([name,r])=>`<button class="region ${state?.region===name?'active':''} ${records[recordKey(name)]?.completed?'complete':''}" data-region="${name}" aria-pressed="${state?.region===name}"><svg viewBox="0 0 32 32" aria-hidden="true">${r.symbol?`<path d="${r.symbol}"/>`:'<circle cx="16" cy="16" r="12"/><ellipse cx="16" cy="16" rx="6" ry="12"/><path d="M4 16h24"/>'}</svg><strong>${name==='World'?'The whole world':name}</strong><small>${regionCountries(name).length} ${state.includeTerritories?'places':'countries'} ${records[recordKey(name)]?.completed?'· ✓':''}</small></button>`).join('');$('collectionProgress').textContent=`${paths.filter(([n])=>n!=='World'&&records[recordKey(n)]?.completed).length} / 6 continents completed`;$('regions').querySelectorAll('button').forEach(b=>b.onclick=()=>requestRegion(b.dataset.region));}
function requestRegion(region,extended=state.includeTerritories,hardMode=state.hardMode,quickCount=0){pendingQuick=quickCount;pendingCatalog=extended;pendingHard=hardMode;if(!ready)return;if(state&&!state.complete&&(state.cursor>0||state.results.length||selected)){pendingRegion=region;$('switchDialog').showModal()}else start(region,null,extended,hardMode,quickCount)}
function start(region,ids,includeTerritories=state?.includeTerritories??true,hardMode=state?.hardMode??false,quickCount=0){quickCount=[5,10,25].includes(quickCount)?quickCount:0;clearAnswerGlow();stopSpin();selected=null;state={region,deck:shuffled(ids||regionCountries(region,includeTerritories).map(c=>c.id)).slice(0,quickCount||Infinity),quickCount,cursor:0,results:[],flagOnly:state?.flagOnly||false,complete:false,practice:!!ids,includeTerritories,hardMode};analytics('quiz_start',{region,collection:includeTerritories?'countries_and_territories':'countries',difficulty:hardMode?'hard':'standard',quiz_length:quickCount||'full'});save();renderRegions();render();recenter();}
function target(){return byId[state.deck[state.cursor]]}function revealed(){return state.results.length>state.cursor}
function setText(id,text){$(id).textContent=text}
function setFlag(country){$('flag').src=`flags/${country.code}.png`;$('flag').alt=state.flagOnly&&!revealed()?'Flag of the country to find':`Flag of ${country.name}`;}
function render(){if(!state)return;selected=null;renderRanks();$('difficulty').value=state.hardMode?'hard':'standard';$('soundButton').setAttribute('aria-pressed',String(audioEnabled));setText('soundButton',audioEnabled?'Sound on':'Sound off');$('soundVolume').value=String(Math.round(soundVolume*100));setText('volumeValue',Math.round(soundVolume*100)+'%');$('mapTheme').value=mapTheme;$('collectionMode').value=state.includeTerritories?'extended':'countries';$('profileDialog').hidden=true;$('review').hidden=true;$('countryFacts').hidden=true;renderRegions();paintCountries();let count=state.deck.length,done=state.results.length,correct=state.results.filter(r=>r.correct).length,percent=Math.round(done/count*100);setText('regionLabel',state.quickCount?`RANDOM ${state.quickCount} · WORLD QUIZ`:`${state.region.toUpperCase()} ${state.practice?'PRACTICE':'EXPEDITION'}`);setText('round',state.complete?'EXPEDITION COMPLETE':`${state.includeTerritories?'PLACE':'COUNTRY'} ${String(state.cursor+1).padStart(2,'0')} / ${count}`);setText('foundLabel',state.includeTerritories?'PLACES FOUND':'COUNTRIES FOUND');setText('percent',`${percent}%`);$('progress').style.width=`${percent}%`;$('found').innerHTML=`${correct}<span> / ${count}</span>`;setText('accuracy',done?Math.round(correct/done*100)+'%':'—');let streak=0;for(let i=state.results.length-1;i>=0&&state.results[i].correct;i--)streak++;setText('streak',streak);setText('best',state.quickCount?'—':records[recordKey(state.region)]?.best!=null?records[recordKey(state.region)].best+'%':'—');$('flagMode').setAttribute('aria-pressed',String(state.flagOnly));$('flagMode').disabled=state.complete;$('feedback').className='feedback';$('feedback').replaceChildren();$('submit').disabled=!ready;$('skip').disabled=!ready||state.complete||revealed();$('flagFrame').hidden=state.complete;$('instruction').innerHTML='Spin the globe. Find the country.<br>Click its shape to select your answer.';setText('panelNote',state.hardMode?'Hard mode · Selection names and found-country hints are hidden.':'Click a found country to revisit its profile.');
 if(state.complete){setText('questionEyebrow',state.practice?'PRACTICE COMPLETE':'EXPEDITION COMPLETE');setText('countryName',correct===count?'A world well known.':'A little closer to the world.');setText('instruction',`You identified ${correct} of ${count} countries correctly. ${correct===count?'Every country, found. Beautifully done.':'Every discovery brings you further.'}`);setText('selection',`${Math.round(correct/count*100)}% accuracy · ${count} countries explored`);$('submit').innerHTML='Explore again <span>↗</span>';setText('mapMessage','Your expedition is complete. Keep your curiosity.');showReview();return}
 const c=target();setFlag(c);setText('questionEyebrow',state.flagOnly&&!revealed()?'FOLLOW THE FLAG':c.territory?'FIND THIS TERRITORY':'FIND THIS COUNTRY');setText('countryName',state.flagOnly&&!revealed()?'Where does this flag belong?':c.name);$('submit').innerHTML=revealed()?(state.cursor===count-1?'See expedition results <span>↗</span>':'Next country <span>↗</span>'):'Check answer <span>↗</span>';$('submit').disabled=!ready||!revealed();setText('selection','◎ Select a country on the globe');setText('mapMessage',ready?'Drag to rotate · Scroll to zoom · Click a country':'Preparing your expedition…');
 if(revealed()){showCountryFacts(c);const r=state.results[state.cursor];setText('selection',r.guess?`Your selection: ${byId[r.guess]?.name||r.guess}`:'You skipped this country');$('feedback').className='feedback visible'+(r.correct?'':' wrong');const strong=document.createElement('strong');strong.textContent=r.correct?'A perfect find.':r.guess?'A new place to remember.':'One for your next adventure.';const detail=document.createElement('span');detail.textContent=`${c.name} · ${c.continent}${c.capital?' · Capital: '+c.capital:''}`;const profileButton=document.createElement('button');profileButton.id='feedbackProfile';profileButton.className='feedback-profile';profileButton.textContent='Country shape & discovery profile ↗';profileButton.disabled=!countryFacts?.countries?.[c.id];profileButton.onclick=openCountryProfile;$('feedback').append(strong,detail,profileButton);if(!r.correct){const locationButton=document.createElement('button');locationButton.className='feedback-profile';locationButton.textContent='Show correct location ↗';locationButton.onclick=revealCorrectLocation;$('feedback').append(locationButton)}setText('instruction',r.correct?'Country identified. Keep exploring.':'The correct country is highlighted in green.');setText('mapMessage',r.correct?`✓ ${c.name} — found`:`${c.name} is highlighted in green`);setText('panelNote','Green: destination · Coral: missed selection.');}
}
function showReview(){const missed=state.results.filter(r=>!r.correct).map(r=>byId[r.id]);if(!missed.length){$('profileDialog').hidden=true;$('review').hidden=true;return}$('review').hidden=false;$('missedFlags').replaceChildren();for(const c of missed){let el=document.createElement('span');el.className='missed-country';let img=document.createElement('img');img.src=`flags/${c.code}.png`;img.alt='';el.append(img,document.createTextNode(c.name));$('missedFlags').append(el)}}
function revealCorrectLocation(){if(!ready||state.complete||!revealed())return;stopSpin();const c=target();map.flyTo({center:c.center,zoom:Math.max(map.getZoom(),c.area<3000?4:2.2),duration:reduced?0:1300,essential:false});setText('mapMessage',`Correct location: ${c.name} · highlighted in green`)}
function check(skip=false){if(!ready||state.complete||revealed()||(!selected&&!skip))return;stopSpin();const c=target(),oldRank=currentRank().title;state.results.push({id:c.id,guess:skip?null:selected,correct:!skip&&selected===c.id});if(state.results[state.cursor].correct)foundPlaces.add(c.id);if(currentRank().title!==oldRank)analytics('rank_earned',{rank:currentRank().title,unique_places:foundPlaces.size});analytics('quiz_answer',{region:state.region,correct:state.results[state.cursor].correct,skipped:skip,place_type:c.territory?'territory':'country'});save();render();if(state.results[state.cursor].correct){playUiSound(currentRank().title!==oldRank?'rank':'correct');pulseCountry(c.id)}else{playUiSound('miss');revealCorrectLocation()}}
function next(){if(!state.complete&&!revealed()){check();return}clearAnswerGlow();playUiSound(!state.complete&&state.cursor===state.deck.length-1?'complete':'next');$('profileDialog').hidden=true;if(state.complete){start(state.region,null,state.includeTerritories,state.hardMode,state.quickCount);return}if(!revealed()){check();return}if(state.cursor===state.deck.length-1){state.complete=true;analytics('quiz_complete',{region:state.region,correct:state.results.filter(r=>r.correct).length,total:state.deck.length});if(!state.practice&&!state.quickCount){let accuracy=Math.round(state.results.filter(r=>r.correct).length/state.deck.length*100);records[recordKey(state.region)]={completed:true,best:Math.max(accuracy,records[recordKey(state.region)]?.best||0)}}save();render();}else{state.cursor++;selected=null;save();render();}}
function paintCountries(){if(!ready||!state)return;const t=MAP_THEMES[mapTheme];const correct=state.hardMode?[]:state.results.filter(r=>r.correct).map(r=>r.id);const r=revealed()?state.results[state.cursor]:null;const active=['in',['get','code'],['literal',regionCountries(state.region).map(c=>c.id)]];const fill=['case',['==',['get','code'],selected||''],t.selected,...(r?[['==',['get','code'],r.id],t.correct,...(r.guess&&!r.correct?[['==',['get','code'],r.guess],t.miss]:[])]:[]),['in',['get','code'],['literal',correct]],t.found,active,t.land,t.muted];map.setPaintProperty('countries','fill-color',fill);map.setPaintProperty('countries','fill-opacity',['case',['==',['get','code'],hoverCode||''],.98,.87]);map.setPaintProperty('borders','line-color',['case',['==',['get','code'],selected||''],t.selectedLine,t.border]);map.setPaintProperty('borders','line-width',['case',['==',['get','code'],selected||''],1.6,.55]);map.setPaintProperty('small-countries','circle-color',fill);map.setPaintProperty('small-countries','circle-stroke-color',['case',['==',['get','code'],selected||''],t.selectedLine,...(r?[['==',['get','code'],r.id],t.correct]:[]),t.border]);map.setFilter('small-countries',['in',['get','code'],['literal',regionCountries(state.region).map(c=>c.id)]]);}
function chooseAt(point){if(!ready)return;stopSpin();const hits=map.queryRenderedFeatures(point,{layers:['small-countries','countries']});const hit=hits.find(f=>eligible(byId[f.properties.code])&&(state.region==='World'||byId[f.properties.code].continent===state.region));if(!hit){setText('mapMessage','Choose a country in this expedition. Zoom in for small countries.');return}const code=hit.properties.code;if(!state.hardMode&&state.results.some(r=>r.id===code&&r.correct)){openCountryProfile(code);return}if(state.complete||revealed())return;selected=code;playUiSound('select');paintCountries();setText('selection',state.hardMode?'◎ Selection ready · Identity hidden':`◎ Selected: ${byId[selected].name}`);$('submit').disabled=false;setText('mapMessage','Click another country to change your selection.');}
function baseZoom(){const fill=state?.region==='World'?.96:.83;return Math.log2(Math.max(200,Math.min($('map').clientWidth*fill,$('map').clientHeight*fill))/210)}
function recenter(){if(!ready)return;stopSpin();map.flyTo({center:REGION_INFO[state.region].center,zoom:baseZoom(),pitch:0,bearing:0,duration:reduced?0:1300,essential:false})}
function stopSpin(){spinning=false;cancelAnimationFrame(raf);$('spin').setAttribute('aria-pressed','false');lastFrame=0}
function rotate(now){if(!spinning)return;if(lastFrame){const c=map.getCenter();map.jumpTo({center:[c.lng+(now-lastFrame)*.003,c.lat]})}lastFrame=now;raf=requestAnimationFrame(rotate)}
function fail(message){$('mapError').hidden=false;setText('mapError',message);$('submit').disabled=true;$('skip').disabled=true;setText('mapMessage','The globe is unavailable. Reload to try again.')}
function graticule(){const features=[];for(let lng=-180;lng<180;lng+=30){features.push({type:'Feature',geometry:{type:'LineString',coordinates:Array.from({length:177},(_,i)=>[lng,i-88])}})}for(let lat=-60;lat<=60;lat+=30){features.push({type:'Feature',geometry:{type:'LineString',coordinates:Array.from({length:361},(_,i)=>[i-180,lat])}})}return {type:'FeatureCollection',features}}

async function loadCountryFacts(){try{const r=await fetch('facts.json');if(!r.ok)throw Error('Facts unavailable');countryFacts=await r.json();if(state&&!state.complete&&revealed()){showCountryFacts(target());}}catch{countryFacts=null;if(state&&!state.complete&&revealed())showCountryFacts(target())}}
function factExcerpt(value,limit=370){if(value.length<=limit)return value;const part=value.slice(0,limit).replace(/\s+\S*$/,'');const date=value.match(/\((?:[^()]*(?:19|20)\d{2}[^()]*)\)/g)?.at(-1);return part+'…'+(date&&!part.includes(date)?' '+date:'')}
function showCountryFacts(c){const f=countryFacts?.countries?.[c.id];$('countryFacts').hidden=false;setText('factsTitle',`A closer look at ${c.name}.`);$('factsOutline').src=`outlines/${c.code}.svg`;$('factsOutline').alt=`Simplified outline of ${c.name}`;$('fullProfile').disabled=!f;const feedbackLink=$('feedbackProfile');if(feedbackLink)feedbackLink.disabled=!f;if(!f){for(const id of ['factLanguages','factReligions','factGovernment'])setText(id,countryFacts?'Profile unavailable.':'Loading country profile…');setText('factSourceNote',countryFacts?'This profile is not available.':'If the facts do not load, refresh the page; your quiz progress is saved.');return}setText('factLanguages',factExcerpt(f.languages));setText('factReligions',factExcerpt(f.religions));setText('factGovernment',factExcerpt(f.government));setText('factSourceNote','Source: World Factbook archive & linked references · Government classifications are archival; estimate dates are retained. Open the full profile for notes and sources.')}
function openCountryProfile(id){const revisit=typeof id==='string';if(!state||(revisit?(state.hardMode||!state.results.some(r=>r.id===id&&r.correct)):(state.complete||!revealed())))return;const c=revisit?byId[id]:target(),f=countryFacts?.countries?.[c.id];if(!f)return;stopSpin();setText('profileEyebrow',(revisit||state.results[state.cursor]?.correct)?'✓ COUNTRY DISCOVERED':'BEYOND THE BORDERS');setText('profileTitle',c.name);setText('profileRegion',c.continent+(c.territory?' · Territory':''));setText('profileRank',`✧ ${currentRank().title} · ${foundPlaces.size} unique places found`);$('profileOutline').src=`outlines/${c.code}.svg`;$('profileOutline').alt=`Simplified main outline of ${c.name}`;$('profileMetrics').replaceChildren();for(const [label,value]of [['Capital',c.capital||'Not specified'],['Population',f.population],['Area',c.area.toLocaleString()+' km²'],['Currency',f.currency]]){const cell=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value||'Not specified';cell.append(dt,dd);$('profileMetrics').append(cell)}$('profileNext').hidden=revisit;setText('profileNext',state.cursor===state.deck.length-1?'See expedition results ↗':'Next country ↗');$('profileFlag').src=`flags/${c.code}.png`;$('profileFlag').alt=`Flag of ${c.name}`;$('profileBody').replaceChildren();for(const [heading,value,note]of [['Location',f.location,''],['Climate',f.climate,''],['Terrain',f.terrain,''],['Languages spoken',f.languages,f.languageNote],['Religions & beliefs',f.religions,f.religionNote],['Government type · reference profile',f.government,f.governmentNote]]){const section=document.createElement('section'),h=document.createElement('h3'),p=document.createElement('p');h.textContent=heading;p.textContent=value;section.append(h,p);if(note){const n=document.createElement('p');n.className='profile-note';n.textContent=note;section.append(n)}$('profileBody').append(section)}$('profileSources').replaceChildren();const heading=document.createElement('h3');heading.textContent='Sources & context';$('profileSources').append(heading);for(const source of [...f.sources,{label:'Country outline · Natural Earth (main territory; distant islands or overseas territories may be omitted)',url:'https://github.com/datasets/geo-countries'}]){const link=document.createElement('a');link.href=source.url;link.target='_blank';link.rel='noreferrer';link.textContent=source.label+' ↗';$('profileSources').append(link)}setText('profileDate','Reference data retrieved October 26, 2026. '+countryFacts.note);$('profileDialog').hidden=false;$('profileDialog').scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'})}

async function init(){try{const responses=await Promise.all([fetch('countries.json'),fetch('world.geojson')]);if(responses.some(r=>!r.ok))throw Error('Country files unavailable');[countries,geo]=await Promise.all(responses.map(r=>r.json()));byId=Object.fromEntries(countries.map(c=>[c.id,c]));const saved=readSaved();records=saved?.records&&typeof saved.records==='object'?saved.records:{};const s=saved?.state;if(s&&REGION_INFO[s.region]&&Array.isArray(s.deck)&&s.deck.length&&s.deck.every(id=>byId[id])&&new Set(s.deck).size===s.deck.length&&Array.isArray(s.results)&&Number.isInteger(s.cursor)&&s.cursor>=0&&s.cursor<s.deck.length&&s.results.length<=s.deck.length){state=s}else{state={region:'Africa',deck:shuffled(regionCountries('Africa').map(c=>c.id)),cursor:0,results:[],flagOnly:false,complete:false,practice:false,includeTerritories:true}}
 audioEnabled=saved?.audioEnabled!==false;soundVolume=typeof saved?.soundVolume==='number'&&Number.isFinite(saved.soundVolume)?Math.max(0,Math.min(1,saved.soundVolume)):.65;mapTheme=Object.hasOwn(MAP_THEMES,saved?.mapTheme)?saved.mapTheme:'midnight';state.hardMode=state.hardMode===true;state.includeTerritories=typeof state.includeTerritories==='boolean'?state.includeTerritories:false;foundPlaces=new Set((Array.isArray(saved?.foundPlaces)?saved.foundPlaces:[]).filter(id=>byId[id]));for(const r of state.results)if(r.correct&&byId[r.id])foundPlaces.add(r.id);
 render();loadCountryFacts();mapboxgl.accessToken='pk.eyJ1Ijoicm9uZG9taW5ndWUiLCJhIjoiYTM4ODdRdyJ9.jcyNgQQolgrKfs6SKBXNJw';map=new mapboxgl.Map({container:'map',style:{version:8,sources:{},layers:[{id:'ocean',type:'background',paint:{'background-color':MAP_THEMES[mapTheme].ocean}}]},center:REGION_INFO[state.region].center,zoom:baseZoom(),minZoom:-1.5,maxZoom:8,projection:'globe',attributionControl:false,renderWorldCopies:false,dragRotate:false,doubleClickZoom:false});map.addControl(new mapboxgl.AttributionControl({compact:true,customAttribution:'Boundaries: Natural Earth'}),'bottom-right');map.on('load',()=>{map.setFog({color:'#284850','high-color':'#1b3545','space-color':'#0b1318','horizon-blend':.12,'star-intensity':.16});map.addSource('grid',{type:'geojson',data:graticule()});map.addLayer({id:'grid',type:'line',source:'grid',paint:{'line-color':'#52737d','line-opacity':.16,'line-width':.6}});map.addSource('world',{type:'geojson',data:geo,tolerance:.15});map.addLayer({id:'countries',type:'fill',source:'world',paint:{'fill-color':'#304c50','fill-opacity':.87}});map.addLayer({id:'answer-glow',type:'line',source:'world',filter:['==',['get','code'],''],paint:{'line-color':'#a8eac7','line-width':9,'line-blur':5,'line-opacity':0}});map.addLayer({id:'answer-ring',type:'line',source:'world',filter:['==',['get','code'],''],paint:{'line-color':'#c6f4d4','line-width':1.6,'line-opacity':0}});map.addLayer({id:'borders',type:'line',source:'world',paint:{'line-color':'#72918e','line-width':.55,'line-opacity':.6}});map.addSource('small',{type:'geojson',data:{type:'FeatureCollection',features:countries.filter(c=>c.area<3000||!geo.features.some(f=>f.properties.code===c.id)).map(c=>({type:'Feature',properties:{code:c.id,continent:c.continent},geometry:{type:'Point',coordinates:c.center}}))}});map.addLayer({id:'small-countries',type:'circle',source:'small',paint:{'circle-radius':['interpolate',['linear'],['zoom'],0,4,3,6,6,9],'circle-color':'#304c50','circle-stroke-color':'#98b9ae','circle-stroke-width':1,'circle-opacity':.95}});ready=true;applyMapTheme();render();map.getCanvas().setAttribute('aria-label','Quiz globe. Arrow keys rotate. Plus and minus zoom. Enter selects the country at the centre.');map.on('click',e=>chooseAt(e.point));map.on('mousemove',e=>{if(state.hardMode&&(state.complete||revealed()))return;const hit=map.queryRenderedFeatures(e.point,{layers:['small-countries','countries']}).find(f=>eligible(byId[f.properties.code])&&(state.region==='World'||byId[f.properties.code].continent===state.region));const code=hit?.properties.code||'';map.getCanvas().style.cursor=code?'pointer':'grab';if(code!==hoverCode){hoverCode=code;paintCountries()}});map.on('dragstart',stopSpin);map.on('zoomstart',e=>{if(e.originalEvent)stopSpin()});map.getCanvas().addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();chooseAt({x:$('map').clientWidth/2,y:$('map').clientHeight/2})}});});map.on('error',e=>{if(!ready)fail('The globe could not load. Check your connection, reload the page, and make sure WebGL is enabled.')});}catch(e){fail('We couldn’t prepare the globe. Check your connection and reload the page. Your saved progress is kept.')}}
$('switchDialog').addEventListener('cancel',()=>{$('collectionMode').value=state.includeTerritories?'extended':'countries';$('difficulty').value=state.hardMode?'hard':'standard'});$('audioSettingsButton').onclick=()=>{const panel=$('audioSettings');panel.hidden=!panel.hidden;$('audioSettingsButton').setAttribute('aria-expanded',String(!panel.hidden))};$('testReward').onclick=()=>{audioEnabled=true;if(soundVolume<=0)soundVolume=.65;$('soundButton').setAttribute('aria-pressed','true');setText('soundButton','Sound on');$('soundVolume').value=String(Math.round(soundVolume*100));setText('volumeValue',Math.round(soundVolume*100)+'%');save();audioStatus('Starting reward chime…');playUiSound('reward')};$('soundVolume').oninput=()=>{const value=Number($('soundVolume').value);soundVolume=Number.isFinite(value)?Math.max(0,Math.min(1,value/100)):.65;setText('volumeValue',Math.round(soundVolume*100)+'%');for(const audio of Object.values(rewardAudio))audio.volume=soundVolume;audioStatus(soundVolume>0?'Sound ready · '+Math.round(soundVolume*100)+'% volume.':'Volume is muted.');save()};$('mapTheme').onchange=()=>{if(!Object.hasOwn(MAP_THEMES,$('mapTheme').value))return;mapTheme=$('mapTheme').value;applyMapTheme();save();playUiSound('select')};$('soundButton').onclick=()=>{audioEnabled=!audioEnabled;$('soundButton').setAttribute('aria-pressed',String(audioEnabled));setText('soundButton',audioEnabled?'Sound on':'Sound off');save();if(audioEnabled)playUiSound('select');else{for(const audio of Object.values(rewardAudio))audio.pause();audioStatus('Sound muted.')}};$('difficulty').onchange=()=>requestRegion(state.region,state.includeTerritories,$('difficulty').value==='hard',state.quickCount);$('collectionMode').onchange=()=>requestRegion(state.region,$('collectionMode').value==='extended',state.hardMode,state.quickCount);$('rankButton').onclick=$('rankDetails').onclick=()=>{$('rankDialog').showModal()};$('closeRanks').onclick=()=>$('rankDialog').close();$('profileNext').onclick=next;$('profileKeepExploring').onclick=()=>{$('profileDialog').hidden=true};$('fullProfile').onclick=openCountryProfile;$('closeProfile').onclick=()=>{$('profileDialog').hidden=true};
for(const n of [5,10,25])$('quick'+n).onclick=()=>requestRegion('World',state.includeTerritories,state.hardMode,n);$('submit').onclick=next;$('skip').onclick=()=>check(true);$('flagMode').onclick=()=>{if(!state||state.complete)return;state.flagOnly=!state.flagOnly;save();const prior=selected;render();if(prior&&!revealed()){selected=prior;paintCountries();setText('selection',state.hardMode?'◎ Selection ready · Identity hidden':`◎ Selected: ${byId[selected].name}`);$('submit').disabled=false}};$('zoomIn').onclick=()=>{stopSpin();map?.zoomIn()};$('zoomOut').onclick=()=>{stopSpin();map?.zoomOut()};$('reset').onclick=recenter;$('spin').onclick=()=>{if(!ready)return;if(spinning){stopSpin();return}spinning=true;$('spin').setAttribute('aria-pressed','true');lastFrame=0;raf=requestAnimationFrame(rotate)};$('how').onclick=()=>{stopSpin();$('help').showModal()};$('closeHelp').onclick=$('helpDone').onclick=()=>$('help').close();$('sources').onclick=()=>$('notes').showModal();$('closeNotes').onclick=()=>$('notes').close();$('regionsButton').onclick=()=>$('regions').scrollIntoView({behavior:reduced?'instant':'smooth',block:'center'});$('cancelSwitch').onclick=()=>{$('switchDialog').close();$('collectionMode').value=state.includeTerritories?'extended':'countries';$('difficulty').value=state.hardMode?'hard':'standard'};$('confirmSwitch').onclick=()=>{$('switchDialog').close();start(pendingRegion,null,pendingCatalog,pendingHard,pendingQuick)};$('retryMissed').onclick=()=>{const ids=state.results.filter(r=>!r.correct).map(r=>r.id);if(ids.length)start(state.region,ids)};document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpin()});init();
